import type { Meta, StoryObj } from '@storybook/vue3-vite'

import { html } from 'common-tags'

import {
  AvatarFallback,
  AvatarGroup,
  AvatarImage,
  AvatarRoot,
} from '@/components/ui/avatar'
import { registryItem } from './_registry'

import AvatarDefaultStory from './AvatarDefaultStory.vue'
import AvatarDefaultSource from './AvatarDefaultStory.vue?raw'

const meta = {
  title: 'Components/UI/Avatar',
  component: AvatarRoot,
  subcomponents: {
    AvatarImage,
    AvatarFallback,
    AvatarGroup,
  },
  tags: ['autodocs'],

  argTypes: {
    shape: {
      control: 'inline-radio',
      options: ['round', 'square'],
    },
    size: {
      control: 'inline-radio',
      options: ['sm', 'md', 'lg', 'xl'],
    },
  },

  args: {
    shape: 'round',
    size: 'md',
  },

  parameters: {
    docs: {
      description: {
        component: registryItem.description,
      },
    },
  },
} satisfies Meta<typeof AvatarRoot>

export default meta
type Story = StoryObj<typeof meta>

export const Default: Story = {
  parameters: {
    docs: {
      source: {
        code: AvatarDefaultSource,
      },
    },
  },

  render: args => ({
    components: { AvatarDefaultStory },

    setup() {
      return { args }
    },

    template: html`
      <AvatarDefaultStory v-bind="args" />
    `,
  }),
}
